sp_widget.script:
(function() {
  data.documents = [];
  data.applicationId = "";

  try {
    data.applicationId = $sp.getParameter("app_id") || "";
    if (!data.applicationId) return;

    var gr = new GlideRecord("sys_attachment");
    gr.addQuery("table_name", "x_1433041_identi_0_application");
    gr.addQuery("table_sys_id", data.applicationId);
    gr.orderByDesc("sys_created_on");
    gr.setLimit(20);
    gr.query();

    while (gr.next()) {
      data.documents.push({
        sys_id: gr.getValue("sys_id"),
        file_name: gr.getValue("file_name"),
        content_type: gr.getValue("content_type"),
        size_bytes: gr.getValue("size_bytes"),
        created_on: gr.getDisplayValue("sys_created_on"),
        created_by: gr.getDisplayValue("sys_created_by")
      });
    }
  } catch (e) {
    gs.error("IBAR Upload History widget error: " + e.message);
  }
})();
